import time

# High Search, Low Knowledge approach: Recursive Fibonacci
def fib_search(n):
    if n <= 1:
        return n
    return fib_search(n - 1) + fib_search(n - 2)

# High Knowledge (Memoized), Low Search approach: Dynamic Programming
