import re

def parse(s):
    tokens = re.findall(r'\(|\)|\d+|[+*]', s)
    def helper(it):
        token = next(it)
        if token == '(':
            lst = []
            while True:
                peek = next(it)
                if peek == ')':
                    break
                it = iter([peek] + list(it))
                lst.append(helper(it))
            return lst
        elif token.isdigit():
            return int(token)
        else:
            return token
    return helper(iter(tokens))

