def filter_models(worlds, cnf):
    # cnf is list of clauses, each clause a list of (var, sign) where sign=True for positive
    def satisfies(w):
        for clause in cnf:
            if not any(w[var] if sign else not w[var] for var,sign in clause):
                return False
        return True
    return [w for w in worlds if satisfies(w)]

