    {"type": "symptom", "name": "fever"},
    {"type": "symptom", "name": "cough"},
    {"type": "lab", "value": "high_wbc"}
]

rules = [
    [("type", "symptom"), ("name", "fever")],               # Rule 1
    [("type", "symptom"), ("name", "cough")],               # Rule 2
    [("type", "lab"), ("value", "high_wbc")],               # Rule 3
    [("type", "symptom"), ("name", "fever"), ("type", "lab"), ("value", "high_wbc")]  # Rule 4 (joins two facts)
]

def naive_match(facts, rule):
    # Try every combination of facts for the rule length
    from itertools import product
    for combo in product(facts, repeat=len(rule)//2):
        ok = True
        for (field, val), fact in zip(rule, combo):
            if fact.get(field) != val:
                ok = False
                break
