from collections import deque
def bfs(start, goal, get_successors):
    queue = deque([[start]])
    visited = {start}
    while queue:
        path = queue.popleft()
        node = path[-1]
        if node == goal: return path
        for next_node in get_successors(node):
            if next_node not in visited:
                visited.add(next_node)
                queue.append(path + [next_node])
    return None

