# Conceptual evaluation of an AND-OR tree node cost
def evaluate_node(node):
    if not node['children']:
        return node['cost']
    if node['type'] == 'OR':
        # Minimum cost among alternatives
        return node['cost'] + min(evaluate_node(c) for c in node['children'])
    elif node['type'] == 'AND':
        # Sum of costs for all required subproblems
        return node['cost'] + sum(evaluate_node(c) for c in node['children'])

