# Simple forward & backward chaining demo using Python dictionaries
# Rule format: {'if': [('A', True), ('B', True)], 'then': ('C', True)}
rules = [
    {'if': [('rain', True)], 'then': ('wet_ground', True)},
    {'if': [('wet_ground', True), ('sun', False)], 'then': ('need_umbrella', True)}
]

facts = {'rain': True, 'sun': False}

# ---------- Forward Chaining ----------
agenda = list(facts.items())
while agenda:
    var, val = agenda.pop(0)
    for r in rules:
        if all(facts.get(p[0], None) == p[1] for p in r['if']):
            cons_var, cons_val = r['then']
            if facts.get(cons_var) != cons_val:
                facts[cons_var] = cons_val
                agenda.append((cons_var, cons_val))
print('Facts after forward chaining:', facts)

# ---------- Backward Chaining ----------

def backward(goal, known, depth=0):
    if known.get(goal[0]) == goal[1]:
        return True
    for r in rules:
        if r['then'] == goal:
            # try to prove all antecedents
            if all(backward(p, known, depth+1) for p in r['if']):
                known[goal[0]] = goal[1]
                return True
    return False

known = facts.copy()
print('Can we prove need_umbrella?', backward(('need_umbrella', True), known))
print('Known after backward chaining:', known)

