# Simple Hill Climbing to maximize f(x) = -x^2 + 4x

def objective_function(x):
    return - (x ** 2) + (4 * x)

def hill_climbing():
    current_x = 0.0
    step_size = 0.1
    max_iterations = 1000

    for _ in range(max_iterations):
        current_val = objective_function(current_x)

        # Generate neighbors (left and right)
        next_x_left = current_x - step_size
        next_x_right = current_x + step_size

        val_left = objective_function(next_x_left)
        val_right = objective_function(next_x_right)

        # Find the best neighbor
        if val_left > current_val and val_left >= val_right:
            current_x = next_x_left
        elif val_right > current_val and val_right >= val_left:
            current_x = next_x_right
        else:
            break # Reached peak

    return current_x, objective_function(current_x)

x_opt, val_opt = hill_climbing()
